class Solution {
public:
    vector<string> letterCombinations(string digits) {
        if (digits.empty()) return {};
        vector<string> mapping = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
        vector<string> res = {""};
        for (char d : digits) {
            vector<string> nxt;
            string letters = mapping[d - '0'];
            for (string &prefix : res) {
                for (char c : letters) {
                    nxt.push_back(prefix + c);
                }
            }
            res = move(nxt);
        }
        return res;
    }
};

